LOCAL PROCEDURE Fn_UpdateP2BItem@3(Opt_UpdateType@1003 : 'Insert,Modify,Delete,Rename');
VAR
  Rec_P2BItem@1001 : Record 50017;
BEGIN
  //T24.01
  CASE Opt_UpdateType OF
    Opt_UpdateType::Insert :
      BEGIN
        Rec_P2BItem.INIT;
        Rec_P2BItem."No." := "No.";
        Rec_P2BItem.Description := Description;
        Rec_P2BItem."Base Unit of Measure" := "Base Unit of Measure";
        Rec_P2BItem."Global Dimension 1 Code" := "Global Dimension 1 Code";
        Rec_P2BItem."Item Category Code" := "Item Category Code";
        Rec_P2BItem."Product Group Code" := "Product Group Code";
        Rec_P2BItem.INSERT;
      END;
    Opt_UpdateType::Modify :
      BEGIN
        IF Rec_P2BItem.GET("No.") THEN BEGIN
          Rec_P2BItem.Description := Description;
          Rec_P2BItem."Base Unit of Measure" := "Base Unit of Measure";
          Rec_P2BItem."Global Dimension 1 Code" := "Global Dimension 1 Code";
          Rec_P2BItem."Item Category Code" := "Item Category Code";
          Rec_P2BItem."Product Group Code" := "Product Group Code";
          Rec_P2BItem.MODIFY;
        END;
      END;
    Opt_UpdateType::Delete :
      BEGIN
        IF Rec_P2BItem.GET("No.") THEN
          Rec_P2BItem.DELETE;
      END;
    Opt_UpdateType::Rename :
      BEGIN
        IF Rec_P2BItem.GET(xRec."No.") THEN
          Rec_P2BItem.DELETE;

        Rec_P2BItem.INIT;
        Rec_P2BItem."No." := "No.";
        Rec_P2BItem.Description := Description;
        Rec_P2BItem."Base Unit of Measure" := "Base Unit of Measure";
        Rec_P2BItem."Global Dimension 1 Code" := "Global Dimension 1 Code";
        Rec_P2BItem."Item Category Code" := "Item Category Code";
        Rec_P2BItem."Product Group Code" := "Product Group Code";
        Rec_P2BItem.INSERT;
      END;
  END;
  //T24.01
