LOCAL PROCEDURE CreateSalesLine@96(VAR TempSalesLine@1000 : TEMPORARY Record 37);
BEGIN
  SalesLine.INIT;
  SalesLine."Line No." := SalesLine."Line No." + 10000;
  SalesLine.VALIDATE(Type,TempSalesLine.Type);
  IF TempSalesLine."No." = '' THEN BEGIN
    SalesLine.VALIDATE(Description,TempSalesLine.Description);
    SalesLine.VALIDATE("Description 2",TempSalesLine."Description 2");
  END ELSE BEGIN
    SalesLine.VALIDATE("No.",TempSalesLine."No.");
    IF SalesLine.Type <> SalesLine.Type::" " THEN BEGIN
      SalesLine.VALIDATE("Unit of Measure Code",TempSalesLine."Unit of Measure Code");
      //T30.01
      SalesLine."Location Code" := TempSalesLine."Location Code";
      SalesLine.Owner := TempSalesLine.Owner;
      //T30.01
      SalesLine.VALIDATE("Variant Code",TempSalesLine."Variant Code");
      IF TempSalesLine.Quantity <> 0 THEN BEGIN
        SalesLine.VALIDATE(Quantity,TempSalesLine.Quantity);
        SalesLine.VALIDATE("Qty. to Assemble to Order",TempSalesLine."Qty. to Assemble to Order");
      END;
      SalesLine."Purchase Order No." := TempSalesLine."Purchase Order No.";
      SalesLine."Purch. Order Line No." := TempSalesLine."Purch. Order Line No.";
      SalesLine."Drop Shipment" := SalesLine."Purch. Order Line No." <> 0;
    END;
  END;
  SalesLine.INSERT;
END;

LOCAL PROCEDURE CreateItemChargeAssgntSales@83(VAR ItemChargeAssgntSales@1001 : Record 5809;VAR TempItemChargeAssgntSales@1000 : TEMPORARY Record 5809;VAR TempSalesLine@1002 : TEMPORARY Record 37;VAR TempInteger@1003 : TEMPORARY Record 2000000026);
BEGIN
  IF TempSalesLine.FINDSET THEN
    REPEAT
      TempItemChargeAssgntSales.SETRANGE("Document Line No.",TempSalesLine."Line No.");
      IF TempItemChargeAssgntSales.FINDSET THEN BEGIN
        REPEAT
          TempInteger.FINDFIRST;
          ItemChargeAssgntSales.INIT;
          ItemChargeAssgntSales := TempItemChargeAssgntSales;
          ItemChargeAssgntSales."Document Line No." := TempInteger.Number;
          ItemChargeAssgntSales.VALIDATE("Unit Cost",0);
          ItemChargeAssgntSales.INSERT;
        UNTIL TempItemChargeAssgntSales.NEXT = 0;
        TempInteger.DELETE;
      END;
    UNTIL TempSalesLine.NEXT = 0;
END;

PROCEDURE UpdatePriorityCustomer@1000000001(PCustomerNo@1000000000 : Code[20];PSalespersonCode@1000000001 : Code[10];PPriorityCustomer@1000000002 : Boolean;PTypeUpdate@1000000003 : Integer);
VAR
  LCustomer@1000000004 : Record 18;
  LSalesHeader@1000000005 : Record 36;
  LSalesLine@1000000006 : Record 37;
  LItem@1000000007 : Record 27;
  LItemSOS@1000000008 : Boolean;
BEGIN
  {D32.02}

  // Periksa dulu apakah Tipe Dokumen adalah Order atau Return Order, jika bukan ke-2nya validasi digagalkan
  IF ("Document Type" <> "Document Type"::Order) AND ("Document Type" <> "Document Type"::"Return Order") THEN
     EXIT;
  // Periksa dulu apakah responsibility center adalah MAS JKT atau bukan
  //IF "Responsibility Center" <> 'MAS JKT' THEN
  //IF "Responsibility Center" <> 'OFFICE CTR' THEN //FDR 28 Jun 2010
  IF "Responsibility Center" <> 'RETAIL DEP' THEN //ARI AGUST 2010
  BEGIN
     // Periksa jika bukan MAS JKT maka transaksi tidak boleh priority customer
     IF PPriorityCustomer THEN
        ERROR('Priority customer hanya untuk responsibility center RETAIL DEP ... ');
     EXIT;
  END;

  // Periksa jika sudah ada line item yg terinput, maka proses dibatalkan
  {LSalesLine.RESET;
  LSalesLine.SETFILTER("Document No.","No.");
  LSalesLine.SETRANGE(Type,LSalesLine.Type::Item);
  IF LSalesLine.FIND('-') THEN
     ERROR('Item Line sudah terinput, silahkan hapus item line lebih dulu ... '); }

  CALCFIELDS("Salesperson PC");

  // Update otomatis dari system
  IF PTypeUpdate = 1 THEN
  BEGIN
     IF ("Salesperson PC" = PSalespersonCode) AND ("Salesperson PC" <> '') THEN
     BEGIN
        "Priority Customer" := TRUE;
        {MESSAGE('SAMA');
        MESSAGE("Sell-to Customer No.");
        MESSAGE("BEX PC");}
     END
     ELSE
     BEGIN
        "Priority Customer" := FALSE;
        {MESSAGE('TIDAK SAMA');
        MESSAGE("Sell-to Customer No.");
        MESSAGE("BEX PC");}
     END;
     MODIFY;
  END;

  // Update dari user
  IF PTypeUpdate = 2 THEN
  BEGIN
     IF "Salesperson PC" <> '' THEN BEGIN
        IF PPriorityCustomer THEN
           IF "Salesperson PC" <> PSalespersonCode THEN
              ERROR('Salesperson Code tidak sesuai dengan priority customernya ');
     END
     ELSE
        IF PPriorityCustomer THEN
           ERROR('Perubahan priority customer tidak dapat dilakukan, karena bukan priority customer ');
  END;
END;

PROCEDURE SetDocDate@70(par_DocDateDefault@1002 : Date;par_BaseCalcDate@1000 : Date) : Date;
VAR
  lVar_NewDocDate@1003 : Date;
  lRec_Cust@1004 : Record 18;
  lRec_BaseCalendarChange@1001 : Record 7601;
  lVar_NonWorkingDay@1006 : Boolean;
  lVar_EmptyText@1005 : Text[50];
BEGIN
  //T28.01
  lVar_NewDocDate := par_DocDateDefault;

  IF "Document Type" IN ["Document Type"::Order,"Document Type"::"Return Order"] THEN BEGIN
    lVar_NonWorkingDay := TRUE;
    lRec_Cust.RESET;
    lRec_Cust.SETRANGE("No.","Sell-to Customer No.");
    lRec_Cust.SETFILTER("Base Calendar Code",'<>%1','');
    IF lRec_Cust.FINDFIRST THEN BEGIN

      lVar_NewDocDate := par_BaseCalcDate + 1;

      WHILE lVar_NonWorkingDay DO BEGIN
        lRec_BaseCalendarChange.RESET;
        lRec_BaseCalendarChange.SETRANGE("Base Calendar Code",lRec_Cust."Base Calendar Code");
        lRec_BaseCalendarChange.SETRANGE(Date,lVar_NewDocDate);
        lRec_BaseCalendarChange.SETRANGE(Nonworking,TRUE);
        IF lRec_BaseCalendarChange.FINDFIRST THEN
          lVar_NewDocDate += 1
        ELSE BEGIN
          lVar_NonWorkingDay := CalendarMgmt.CheckDateStatus(lRec_Cust."Base Calendar Code",lVar_NewDocDate,lVar_EmptyText);
          IF lVar_NonWorkingDay THEN
            lVar_NewDocDate += 1;
        END
      END;
    END;
  END;

  EXIT(lVar_NewDocDate);
  //T28.01
END;

PROCEDURE CheckExtDocument@71();
VAR
  SalesHeader@1000 : Record 36;
  SalesShipmentH@1001 : Record 110;
  IsExists@1002 : Boolean;
BEGIN
  SalesHeader.SETFILTER("No.",'<>%1',"No.");
  SalesHeader.SETFILTER("External Document No.","External Document No.");
  IF SalesHeader.FINDFIRST THEN
     IsExists := TRUE;

