  BEGIN
    SalesShipmentH.SETFILTER("Order No.",'<>%1',"No.");
    SalesShipmentH.SETFILTER("External Document No.","External Document No.");
    IF SalesShipmentH.FINDFIRST THEN
       IsExists := TRUE;
