  IF IsExists THEN
     MESSAGE('External Document No. sudah pernah dimasukkan');
END;

LOCAL PROCEDURE InsertDefDimDept@72();
VAR
  DefDim@1000 : Record 352;
  recNoSeri@1001 : Record 308;
  def_dept@1002 : Code[10];
BEGIN
  IF(Vsalesperson.GET("Salesperson Code")) THEN
  BEGIN
    IF Vsalesperson."Global Dimension 1 Code" = '' THEN
    BEGIN
        def_dept := '';
        IF recNoSeri.GET("No. Series") THEN
        BEGIN
            def_dept := recNoSeri."Global Dimension 1 Code";
        END;

        IF(def_dept = '') THEN ERROR('Default Departmen kosong');

        DefDim.SETRANGE("Table ID",DATABASE::"Salesperson/Purchaser");
        DefDim.SETRANGE("No.","Salesperson Code");
        DefDim.SETRANGE("Dimension Code",'DEPARTMENT');
        IF NOT DefDim.FINDFIRST THEN
        BEGIN
            DefDim.INIT;
            DefDim."Table ID" := DATABASE::"Salesperson/Purchaser";
            DefDim."No." := "Salesperson Code";
            DefDim."Dimension Code" := 'DEPARTMENT';
            DefDim."Dimension Value Code" := def_dept;
            DefDim.INSERT;
        END ELSE BEGIN
            DefDim."Dimension Value Code" := def_dept;
            DefDim.MODIFY;
        END;
    END;
  END;
END;
